   353→    func test_transaction() {
   354→        print("\n=== Test 5: Transaction COMMIT & ROLLBACK ===");
   355→
   356→        let s = make_users_schema();
   357→        let t = schema.table_new(s);
   358→
   359→        // 시나리오 1: COMMIT
   360→        let tx1 = transaction.tx_begin();
   361→        let row1 = make_user_row(1, "Alice", 30, true);
   362→        let id1, err1 = transaction.tx_insert(&tx1, &t, row1);
   363→        let t1 = assert_true(err1 == transaction.TX_OK, "tx_insert ok");
   364→        print_result(t1);
   365→
   366→        transaction.tx_commit(&tx1);
   367→        let t2 = assert_true(transaction.tx_is_committed(tx1), "tx committed");
   368→        print_result(t2);
   369→
   370→        let _, found1 = t.table_get(id1);
   371→        let t3 = assert_true(found1, "committed row exists");
   372→        print_result(t3);
   373→
   374→        // 시나리오 2: ROLLBACK INSERT
   375→        let tx2 = transaction.tx_begin();
   376→        let row2 = make_user_row(2, "Bob", 25, false);
   377→        let id2, err2 = transaction.tx_insert(&tx2, &t, row2);
   378→
   379→        transaction.tx_rollback(&tx2, &t);
   380→        let t4 = assert_true(transaction.tx_is_rolled_back(tx2), "tx2 rolled back");
   381→        print_result(t4);
   382→
   383→        let _, found2 = t.table_get(id2);
   384→        let t5 = assert_true(!found2, "rolled back row not found");
   385→        print_result(t5);
   386→
   387→        // 시나리오 3: ROLLBACK UPDATE
   388→        let tx3 = transaction.tx_begin();
   389→        let err_upd = transaction.tx_update_int(&tx3, &t, id1, 2, 99);  // age → 99
   390→        let t6 = assert_true(err_upd == transaction.TX_OK, "tx_update_int ok");
   391→        print_result(t6);
   392→
   393→        // 롤백 전 확인
   394→        let before_rb, _ = t.table_get(id1);
   395→        let t7 = assert_eq_i64(before_rb.int_vals[1], 99, "age==99 before rollback");
   396→        print_result(t7);
   397→
   398→        transaction.tx_rollback(&tx3, &t);
   399→
   400→        // 롤백 후 확인 (age가 30으로 복구)
   401→        let after_rb, _ = t.table_get(id1);
   402→        let t8 = assert_eq_i64(after_rb.int_vals[1], 30, "age==30 after rollback");
   403→        print_result(t8);
   404→
   405→        // 시나리오 4: 비활성 트랜잭션 연산 거부
   406→        let tx4 = transaction.tx_begin();
   407→        transaction.tx_commit(&tx4);
   408→        let row3 = make_user_row(3, "Charlie", 35, true);
   409→        let _, err_after = transaction.tx_insert(&tx4, &t, row3);
   410→        let t9 = assert_true(err_after == transaction.TX_ERR_NOT_ACTIVE, "committed tx rejects insert");
   411→        print_result(t9);
   412→
   413→        print(transaction.tx_stats(tx1));
   414→        print(transaction.tx_stats(tx2));
   415→        print("Transaction tests completed");
   416→    }
