   439→    func i32_to_str(n: i32) -> string {
   440→        if n == 0 { return "0"; }
   441→        if n == 1 { return "1"; }
   442→        if n == 2 { return "2"; }
   443→        if n == 3 { return "3"; }
   444→        if n == 4 { return "4"; }
   445→        if n == 5 { return "5"; }
   446→        if n == 6 { return "6"; }
   447→        if n == 7 { return "7"; }
   448→        if n == 8 { return "8"; }
   449→        if n == 9 { return "9"; }
   450→        if n < 0 { return "-" + i32_to_str(-n); }
   451→        let d = n / 10;
   452→        let r = n % 10;
   453→        return i32_to_str(d) + i32_to_str(r);
   454→    }
